#!/bin/bash
# gaussian-16 (gaussian 16) on zeus:alon_q; generated by `rag-drg servers submit` from servers.yaml
#PBS -N CH4O_opt_freq
#PBS -q alon_q
#PBS -l select=1:ncpus=16:mem=64gb
#PBS -l walltime=48:00:00
#PBS -j oe

WORKDIR="$PBS_O_WORKDIR"
JOBID="${PBS_JOBID%%.*}"
cd "$WORKDIR"

# --- gaussian-16: absolute paths, no environment modules ---
export g16root="/usr/local"
source /usr/local/g16/setup.sh
GAUSSIAN=/usr/local/g16/g16

# --- per-job scratch ---
SCRATCH="/gtmp/$USER/$JOBID"
mkdir -p "$SCRATCH"

# on exit, also after a walltime kill or scancel/qdel/condor_rm (SIGTERM): copy back and clean up
cleanup() {
    cd "$WORKDIR" || true
    rm -rf "$SCRATCH"
}
trap cleanup EXIT
trap 'exit 143' TERM INT

export GAUSS_SCRDIR="$SCRATCH"
cd "$WORKDIR"
"$GAUSSIAN" < "methanol.gjf" > "methanol.log"
